#include <bits/stdc++.h>
using namespace std;

struct Orient {
    vector<pair<int,int>> cells;
    int w, h;
    int r, f;
};

vector<Orient> getOrients(const vector<pair<int,int>>& cells) {
    vector<Orient> res;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> tr;
            for (auto [x, y] : cells) {
                int tx = x, ty = y;
                if (f) tx = -tx;
                for (int rr = 0; rr < r; rr++) {
                    int nx = ty, ny = -tx;
                    tx = nx; ty = ny;
                }
                tr.push_back({tx, ty});
            }
            int minx = INT_MAX, miny = INT_MAX;
            for (auto [x, y] : tr) { minx = min(minx, x); miny = min(miny, y); }
            for (auto& [x, y] : tr) { x -= minx; y -= miny; }
            sort(tr.begin(), tr.end());
            if (seen.insert(tr).second) {
                int mx = 0, my = 0;
                for (auto [x, y] : tr) { mx = max(mx, x); my = max(my, y); }
                res.push_back({tr, mx+1, my+1, r, f});
            }
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ks(n);
    vector<vector<pair<int,int>>> rawCells(n);
    int totalCells = 0;
    for (int i = 0; i < n; i++) {
        cin >> ks[i];
        rawCells[i].resize(ks[i]);
        for (int j = 0; j < ks[i]; j++) {
            cin >> rawCells[i][j].first >> rawCells[i][j].second;
        }
        totalCells += ks[i];
    }

    vector<vector<Orient>> allOrients(n);
    for (int i = 0; i < n; i++) {
        allOrients[i] = getOrients(rawCells[i]);
    }

    // Sort pieces: larger first, then fewer orientations
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        if (ks[a] != ks[b]) return ks[a] > ks[b];
        return allOrients[a].size() < allOrients[b].size();
    });

    int bestArea = INT_MAX;
    int bestW = 0, bestH = 0;
    vector<int> bestX(n), bestY(n), bestR(n), bestF(n);

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> int {
        return (int)chrono::duration_cast<chrono::milliseconds>(
            chrono::steady_clock::now() - startTime).count();
    };

    int sqrtA = max(1, (int)ceil(sqrt((double)totalCells)));

    // Find max piece width across all orientations
    int maxPieceW = 0, maxPieceH = 0;
    for (int i = 0; i < n; i++) {
        for (auto& o : allOrients[i]) {
            maxPieceW = max(maxPieceW, o.w);
            maxPieceH = max(maxPieceH, o.h);
        }
    }

    // Generate candidate widths
    vector<int> candidates;
    for (int w = max(maxPieceW, sqrtA - 30); w <= sqrtA + 100; w++) {
        if (w >= maxPieceW) candidates.push_back(w);
    }
    for (int w = sqrtA + 100; w <= sqrtA * 3; w += 5) {
        candidates.push_back(w);
    }
    // Also try wider as safety
    candidates.push_back(totalCells);

    // Remove duplicates and sort
    sort(candidates.begin(), candidates.end());
    candidates.erase(unique(candidates.begin(), candidates.end()), candidates.end());

    for (int W : candidates) {
        if (elapsed() > 8500) break;
        if (W < maxPieceW) continue;

        // Skyline array
        vector<int> skyline(W, 0);

        // Use unordered_set for occupied cells
        unordered_set<long long> occupied;
        auto key = [&](int x, int y) -> long long { return (long long)x * 1000000LL + y; };

        vector<int> px(n), py(n), pr(n), pf(n);
        bool valid = true;
        int currentMaxH = 0;

        for (int idx = 0; idx < n; idx++) {
            int i = order[idx];

            int bestScore = INT_MAX;
            int bx = -1, by = -1;
            int boi = -1; // best orientation index

            for (int oi = 0; oi < (int)allOrients[i].size(); oi++) {
                auto& ori = allOrients[i][oi];
                if (ori.w > W) continue;

                for (int x = 0; x <= W - ori.w; x++) {
                    // Compute minimum y from skyline
                    int minY = 0;
                    for (auto [cx, cy] : ori.cells) {
                        int needed = skyline[x + cx] - cy;
                        if (needed > minY) minY = needed;
                    }
                    if (minY < 0) minY = 0;

                    // Search from minY
                    bool found = false;
                    int y = minY;
                    for (int tries = 0; tries < 30 && !found; tries++, y++) {
                        bool ok = true;
                        for (auto [cx, cy] : ori.cells) {
                            if (occupied.count(key(x+cx, y+cy))) { ok = false; break; }
                        }
                        if (ok) found = true; else continue;
                        if (found) {
                            int mh = 0;
                            for (auto [cx, cy] : ori.cells) mh = max(mh, y+cy+1);
                            int score = max(currentMaxH, mh);
                            // Tiebreak: prefer lower y, then lower x
                            int fullScore = score * 1000000 + mh * 1000 + x;
                            if (fullScore < bestScore) {
                                bestScore = fullScore;
                                bx = x; by = y; boi = oi;
                            }
                            break; // found for this x, move on
                        }
                    }
                    // Early exit if we placed at skyline level 0
                    if (found && by == 0 && bestScore <= currentMaxH * 1000000 + 1000) break;
                }
            }

            if (boi < 0) { valid = false; break; }

            auto& ori = allOrients[i][boi];
            px[i] = bx; py[i] = by; pr[i] = ori.r; pf[i] = ori.f;
            for (auto [cx, cy] : ori.cells) {
                occupied.insert(key(bx+cx, by+cy));
                skyline[bx+cx] = max(skyline[bx+cx], by+cy+1);
                currentMaxH = max(currentMaxH, by+cy+1);
            }
        }

        if (!valid) continue;

        int H = currentMaxH;
        long long area = (long long)W * H;
        if (area < bestArea || (area == bestArea && (H < bestH || (H == bestH && W < bestW)))) {
            bestArea = area;
            bestW = W; bestH = H;
            bestX = px; bestY = py; bestR = pr; bestF = pf;
        }
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) {
        cout << bestX[i] << " " << bestY[i] << " " << bestR[i] << " " << bestF[i] << "\n";
    }
    return 0;
}
